// Long-polling de Telegram. El offset vive en la static data del workflow, asi
// que sobrevive reinicios y cortes de luz: cada mensaje se procesa UNA vez.
//
// POR QUE POLLING Y NO EL NODO "Telegram Trigger": ese nodo registra un webhook
// y Telegram necesita ENTRAR a n8n desde internet. S1 esta detras del router del
// local, sin IP publica. Con polling S1 SALE a internet (que ya puede) y no hay
// que abrir puertos ni depender de un tunel que se caiga.
const est = $getWorkflowStaticData('global');
const token = $env.TELEGRAM_BOT_TOKEN;
if (!token) throw new Error('Falta TELEGRAM_BOT_TOKEN en el entorno de n8n');

const offset = est.offset ?? 0;
const resp = await this.helpers.httpRequest({
  url: `https://api.telegram.org/bot${token}/getUpdates`,
  qs: { offset, timeout: 0, allowed_updates: JSON.stringify(['message']) },
  json: true,
});
if (!resp.ok) throw new Error('getUpdates fallo: ' + JSON.stringify(resp));

const permitidos = String($env.TELEGRAM_ALLOWED_IDS || '')
  .split(',').map((s) => s.trim()).filter(Boolean);

const out = [];
let maxId = offset - 1;
for (const up of resp.result || []) {
  maxId = Math.max(maxId, up.update_id);
  const msg = up.message;
  if (!msg) continue;
  const chatId = msg.chat?.id;
  const fromId = String(msg.from?.id ?? '');
  // Whitelist. Sin lista configurada NO se acepta a nadie: un bot de Telegram
  // es publico y cualquiera que adivine el nombre puede escribirle.
  if (!permitidos.length || !permitidos.includes(fromId)) continue;

  let fileId = null;
  if (Array.isArray(msg.photo) && msg.photo.length) {
    fileId = msg.photo[msg.photo.length - 1].file_id;   // mayor resolucion
  } else if (msg.document) {
    const mt = msg.document.mime_type || '';
    if (mt.startsWith('image/') || mt === 'application/pdf') fileId = msg.document.file_id;
  }
  out.push({ json: { chatId, fromId, fileId, sinArchivo: !fileId } });
}
// El offset avanza SIEMPRE, aun si un mensaje falla despues: si no, una factura
// ilegible se reprocesaria en loop cada minuto para siempre.
est.offset = maxId + 1;
return out;

// getFile devuelve un file_path; el binario se baja de /file/bot<token>/<path>.
// Se hace en un Code node (y no en dos HTTP Request) para tener el buffer en
// memoria y calcular el sha256 sin pasar por disco.
const token = $env.TELEGRAM_BOT_TOKEN;
const out = [];
for (const item of $input.all()) {
  const { fileId, chatId } = item.json;
  const meta = await this.helpers.httpRequest({
    url: `https://api.telegram.org/bot${token}/getFile`,
    qs: { file_id: fileId }, json: true,
  });
  if (!meta.ok) throw new Error('getFile fallo: ' + JSON.stringify(meta));
  const filePath = meta.result.file_path;
  const buf = await this.helpers.httpRequest({
    url: `https://api.telegram.org/file/bot${token}/${filePath}`,
    encoding: 'arraybuffer',
  });
  const bin = Buffer.from(buf);
  const crypto = require('crypto');
  const hash = crypto.createHash('sha256').update(bin).digest('hex');
  const nombre = filePath.split('/').pop() || 'factura';
  const mime = nombre.toLowerCase().endsWith('.pdf') ? 'application/pdf' : 'image/jpeg';
  out.push({
    json: { chatId, hash, nombre, mime },
    binary: { data: await this.helpers.prepareBinaryData(bin, nombre, mime) },
  });
}
return out;

// Mapea la salida del OCR al contrato de POST /api/v1/ingest/facturas.
// El contrato del programa SI esta verificado (apps/api/src/routes/ingest.ts);
// lo que puede cambiar es la FORMA en que LlamaCloud devuelve los datos: si
// cambia, se toca SOLO la funcion `leer()` de abajo.
const out = [];
for (const item of $input.all()) {
  const { chatId, hash } = item.json;
  const crudo = item.json.body ?? item.json;
  const fallo = item.json.statusCode && item.json.statusCode >= 400;

  // Aplana la respuesta: LlamaCloud anida los campos segun la version.
  const d = crudo?.data ?? crudo?.result ?? crudo?.extraction ?? crudo ?? {};
  const leer = (...rutas) => {
    for (const r of rutas) {
      let v = d;
      for (const k of r.split('.')) v = v?.[k];
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return undefined;
  };
  const num = (v) => {
    if (v === undefined || v === null || v === '') return undefined;
    const n = Number(String(v).replace(/[^0-9.,-]/g, '').replace(/\.(?=\d{3}\b)/g, '').replace(',', '.'));
    return Number.isFinite(n) ? n : undefined;
  };

  const total = num(leer('montos.total', 'total', 'importe_total'));
  const proveedor = leer('proveedor.nombre', 'proveedor', 'razon_social', 'emisor.nombre');
  const numero = leer('comprobante.numero', 'numero', 'nro_comprobante');

  const problemas = [];
  if (fallo) problemas.push('el OCR devolvio error');
  if (!total || total <= 0) problemas.push('no se leyo el total');
  if (!proveedor) problemas.push('no se leyo el proveedor');
  if (!numero) problemas.push('no se leyo el numero de comprobante');

  // Sin estos tres no se puede crear la factura: se avisa y se corta.
  if (problemas.length) {
    out.push({ json: { chatId, error: true, problemas } });
    continue;
  }

  const items = (leer('items', 'detalle', 'lineas') || []).map((it) => ({
    descripcion: String(it.descripcion ?? it.description ?? it.detalle ?? '').slice(0, 300),
    cantidad: num(it.cantidad ?? it.quantity),
    unidad: it.unidad ?? it.unit,
    precioUnitario: num(it.precioUnitario ?? it.precio_unitario ?? it.unit_price),
    alicuotaIva: num(it.alicuotaIva ?? it.iva),
    subtotal: num(it.subtotal ?? it.importe),
  })).filter((it) => it.descripcion);

  // Descuadre: no bloquea (el humano valida igual) pero baja la confianza y
  // deja la razon escrita para que quien revisa sepa donde mirar.
  const suma = items.reduce((a, it) => a + (it.subtotal || 0), 0);
  const descuadra = items.length > 0 && Math.abs(total - suma) > total * 0.05;
  const confianza = num(leer('ocr.confianza', 'confidence')) ?? (descuadra ? 0.5 : 0.8);

  out.push({ json: {
    chatId,
    _resumen: { proveedor, total },
    payload: {
      adjunto: { hash },
      proveedor: { nombre: String(proveedor).slice(0, 120), cuit: leer('proveedor.cuit', 'cuit') },
      comprobante: {
        tipo: leer('comprobante.tipo', 'tipo') ?? 'OTRO',
        puntoVenta: leer('comprobante.puntoVenta', 'punto_venta'),
        numero: String(numero).slice(0, 40),
        fechaEmision: leer('comprobante.fechaEmision', 'fecha_emision', 'fecha')
                      ?? new Date().toISOString().slice(0, 10),
        fechaVencimiento: leer('comprobante.fechaVencimiento', 'fecha_vencimiento'),
      },
      montos: {
        neto: num(leer('montos.neto', 'neto')),
        ivaTotal: num(leer('montos.ivaTotal', 'iva')),
        iva21: num(leer('montos.iva21')),
        iva10_5: num(leer('montos.iva10_5')),
        total,
      },
      items,
      ocr: { confianza, payload: crudo },
      observaciones: descuadra ? 'revisar: los items no suman el total' : undefined,
    },
  }});
}
return out;

// Un solo nodo arma TODAS las respuestas y las manda. Centralizarlo evita que
// una rama quede muda (que es como se pierde una factura sin que nadie note).
const token = $env.TELEGRAM_BOT_TOKEN;
const plata = (n) => Number(n || 0).toLocaleString('es-AR', { minimumFractionDigits: 2 });

for (const item of $input.all()) {
  const j = item.json;
  const chatId = j.chatId;
  if (!chatId) continue;
  let texto;

  if (j.sinArchivo) {
    texto = 'Mandame una *foto* o un *PDF* de la factura.';
  } else if (j.error) {
    texto = '⚠️ No pude leer la factura (' + (j.problemas || []).join('; ') + ').\n'
          + 'Probá con una foto más nítida y derecha, o cargala a mano en el sistema.';
  } else {
    const code = j.statusCode;
    const body = j.body ?? {};
    const r = j._resumen ?? {};
    if (code === 201) {
      texto = `✅ Factura de *${r.proveedor}* por $${plata(r.total)} cargada.\n`
            + 'Queda *sin validar*: revisala y aceptala en Admin → Facturas.';
    } else if (code === 200 && body.duplicate) {
      texto = 'ℹ️ Esa factura ya estaba cargada.';
    } else if (code === 503) {
      texto = '⚠️ La ingesta está deshabilitada en el servidor (falta INGEST_API_TOKEN).';
    } else if (code === 401) {
      texto = '⚠️ El token de ingesta es inválido. Avisale al que administra el sistema.';
    } else {
      texto = `⚠️ El sistema rechazó la factura (${code}). Cargala a mano por ahora.`;
    }
  }

  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${token}/sendMessage`,
    body: { chat_id: chatId, text: texto, parse_mode: 'Markdown' },
    json: true,
  });
}
return $input.all();
